('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--6',1,'{"question":"Ava made a shelter, a safe spot out of the rain. What does “shelter” mean?","choices":["a loud crash","a kind of rain","a short walk","a place that offers cover"],"answer":3,"explanation":""}'::jsonb,'08c9bd0b2c0e55cfd9fc54f4a2424ae9','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--7',1,'{"question":"We had scarce paper, only two sheets for the whole group. What does “scarce” mean?","choices":["easy to tear","hard to get or in short supply","freshly painted","large in size"],"answer":1,"explanation":""}'::jsonb,'dfe99cc36f782e2ce90c3ab737c724c9','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--8',1,'{"question":"The hill was steep, unlike the flat path below. What does “steep” mean?","choices":["entirely level","rising sharply","very sunny","covered with grass"],"answer":1,"explanation":""}'::jsonb,'ad6816843d139ef8a06aa45bc69f0b11','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--9',1,'{"question":"The class examined the leaf carefully, checking each edge. What does “examined” mean?","choices":["looked at closely","wrote on","painted green","threw away"],"answer":0,"explanation":""}'::jsonb,'d7af66a159b64fe7f0ca6db06236571a','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--10',1,'{"question":"The fog began to disperse, and soon we could see the whole yard. What does “disperse” mean?","choices":["spread out and clear away","come down as heavy rain","freeze in place","get darker"],"answer":0,"explanation":""}'::jsonb,'8bd539be5761cce8ea4051057d34ad7d','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--11',1,'{"question":"The hill was barren; no plants grew there. What does “barren” mean here?","choices":["crowded with trees","without plants","under water","full of birds"],"answer":1,"explanation":""}'::jsonb,'2728c29cf474a7c6d0f298ce69f21479','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
('original:elementary--english-language-arts--3--context-clues:elementary--english-language-arts--3--context-clues--12',1,'{"question":"Leaves drifted, floating slowly down the stream. What does “drifted” mean?","choices":["grew on branches","sank like rocks","moved slowly with the water","flew uphill against the wind"],"answer":2,"explanation":""}'::jsonb,'41fc2611836a9d840c12bac3e292d338','official',NULL,NULL,'Grade 3 ELA — Working Out Word Meanings from Context'),
