('original:elementary--english-language-arts--4--vocabulary:elementary--english-language-arts--4--vocabulary--17',1,'{"question":"The trail loops back to its start. What does “loops” mean?","choices":["ends early","sinks down","curves around","breaks apart"],"answer":2,"explanation":""}'::jsonb,'df0f5fa72f31972cf8c726fe9b3cda09','official',NULL,NULL,'Grade 4 ELA — Roots, Affixes, and Precise Word Choice'),
