('original:elementary--english-language-arts--4--vocabulary:elementary--english-language-arts--4--vocabulary--20',1,'{"question":"Which word means “one who teaches”?","choices":["taught","teaching","teacher","teachable"],"answer":2,"explanation":""}'::jsonb,'704fb6a76ba1b1c501c07fa7408d7f55','official',NULL,NULL,'Grade 4 ELA — Roots, Affixes, and Precise Word Choice'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--1',1,'{"question":"Bo slipped a card into his sister''s bag and grinned. He had hidden the crayons when she walked in. What can you infer Bo is planning?","choices":["to take her bag away","a surprise for his sister","to clean the whole room","to hide his shoes"],"answer":1,"explanation":""}'::jsonb,'68a6c2e439b88b9d1cd9fbdc7370ec85','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--2',1,'{"question":"Bo slipped a card into his sister''s bag and grinned. He had hidden the crayons when she walked in. Which clue most supports that idea?","choices":["There was a bag.","Bo could see the room.","His sister walked in.","He slipped a card into her bag."],"answer":3,"explanation":""}'::jsonb,'9910baf3b933a52b0a97034ab49838bd','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--3',1,'{"question":"All the seats were folded up except one row. A hand-lettered sign said “Rehearsal.” A violin case rested by the stage. What will most likely happen soon?","choices":["The stage will become a swimming pool.","The seats will all be sold.","Someone will cook lunch.","People will practice a performance."],"answer":3,"explanation":""}'::jsonb,'ef44c66ead44ca67bca28a9a33363c9f','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--4',1,'{"question":"All the seats were folded up except one row. A hand-lettered sign said “Rehearsal.” A violin case rested by the stage. Which pair of details best supports the inference?","choices":["the room and the doors","the folded seats and the case color","the floor and the walls","the rehearsal sign and violin case"],"answer":3,"explanation":""}'::jsonb,'9c4c9870654df31320b06cac156177f1','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--5',1,'{"question":"Ezra came in with cool cheeks and wet boots. He put his gloves by the heater. What can you infer about the weather outside?","choices":["It is probably hot and dry.","It is always exactly freezing.","It is probably cold and wet.","It is probably warm and windy only."],"answer":2,"explanation":""}'::jsonb,'83520c1c72ae5537f213b4f14dbf6acc','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--6',1,'{"question":"Nora read each instruction twice. When the first corner would not fit, she carefully folded it again. How does Nora seem to approach the task?","choices":["by rushing without checking","by ignoring the directions","with care and persistence","by giving up as soon as possible"],"answer":2,"explanation":""}'::jsonb,'dfec841970f394f707829a055d4f3a8d','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--7',1,'{"question":"Overnight the river rose over the lowest trail. At sunrise a worker carried a rope and a CLOSED sign to its entrance. Why will the worker probably put the rope across the trail?","choices":["to keep visitors away from flooded ground","to show where to fish","to measure the length of a boat","to hold a sign open in strong sun"],"answer":0,"explanation":""}'::jsonb,'dd413d9c319e8eb735da8f11f16a703a','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--8',1,'{"question":"Sam had practiced his speech with his brother many times. Outside the classroom, his notes shook in his hand. How does Sam most likely feel before speaking?","choices":["bored","angry at his brother","certain that he will fall asleep","nervous"],"answer":3,"explanation":""}'::jsonb,'55cc9d3bf48f8908403e8f56d8bc497c','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--9',1,'{"question":"Ina heard a steady tap inside the sink cabinet. A puddle was spreading beneath a pipe. What is likely happening?","choices":["The pipe is leaking.","Ina is washing the dishes.","The tap sound is from the stairs.","Someone put ice inside the cabinet."],"answer":0,"explanation":""}'::jsonb,'22631c994829bb73bd6bef307e7e5f58','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--10',1,'{"question":"A hiker brushed leaf litter aside and pointed to a line of rinsed stones and a mud mark above the bank. What most likely happened before the hike?","choices":["The stones were painted green.","Water rose higher than usual.","The bank was paved.","The leaves fell up from the ground."],"answer":1,"explanation":""}'::jsonb,'362f2ed0828dd829dd35af7294a4ea84','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--11',1,'{"question":"By the time class began, Max''s desk partner had an extra pencil and a clean eraser. Max had brought two of each. Why did Max most likely bring extras?","choices":["to count the chairs","to repair the school desks","to make a sign","to share with someone who might need them"],"answer":3,"explanation":""}'::jsonb,'75d925d0540ceaea77e6b681e2f4ad41','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--12',1,'{"question":"A bent gate leaned open. The seed tray beyond it was empty, and tiny footprints crossed the dirt. What is one reasonable inference about the seed tray?","choices":["A small animal may have eaten the seeds.","The footprints were made by a bus.","The seeds flew to the Moon.","The gate never opened."],"answer":0,"explanation":""}'::jsonb,'e37325726133b321d02de652ff58e1ce','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--13',1,'{"question":"On the way to the recital, Eli tapped a rhythm against his knee and hummed the beginning of a tune. What might Eli be doing?","choices":["checking how long the road is","searching for missing keys","reviewing a piece of music","reading the address aloud"],"answer":2,"explanation":""}'::jsonb,'9e85c326bbf57d3e872718df0e9df725','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--14',1,'{"question":"Before trying the ramp, Tali checked each bolt and asked her teammate to hold the base. Which word best describes Tali''s approach?","choices":["uninterested","cautious","impatient","careless"],"answer":1,"explanation":""}'::jsonb,'eae12bb27589ab470b950c48f1210a82','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--15',1,'{"question":"After recess, Sol dried a bench before setting down the class notebooks. Umbrellas stood open near the door. What most likely happened earlier?","choices":["The umbrellas were used as pencils.","It rained.","It snowed indoors.","The notebooks were washed."],"answer":1,"explanation":""}'::jsonb,'c1f3583625e0481f30011746f08e0e64','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--16',1,'{"question":"The grass in the marked square was just as tall as outside it. The gardener wrote “not yet” on the chart and set another date to check. What was the gardener probably waiting to see?","choices":["where the chart was printed","when sunlight began","a visible difference in grass growth","what name the square had"],"answer":2,"explanation":""}'::jsonb,'a5db75d91ebf565ebc32fe6367aad9eb','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--17',1,'{"question":"Jin put the wide wheels back on after the cart got stuck in loose sand with narrow wheels. What does Jin probably think will help?","choices":["taking every wheel off","making the cart narrower","using wheels that sink less in sand","putting more sand on the path"],"answer":2,"explanation":""}'::jsonb,'ba3f3f680760ad0e7604568b2c9d1e18','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--18',1,'{"question":"Before dinner, Meera checked two bowls and moved the tiny one beside the dog''s bed. What can you infer the tiny bowl might be for?","choices":["all dinner guests","the dog","an outdoor plant","the oven"],"answer":1,"explanation":""}'::jsonb,'d84e25bdfd14c98b87388bc590ef4a80','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--19',1,'{"question":"“We still have ten minutes,” Ren said, but kept glancing at the clock and hurrying through his work. What do Ren''s actions suggest?","choices":["He is worried about time.","He forgot how to read.","He wants the room to get darker.","He hopes to work all night."],"answer":0,"explanation":""}'::jsonb,'695f599c5bb34019aa2173ad26eca352','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--4--inference:elementary--english-language-arts--4--inference--20',1,'{"question":"The note on the garden bed read, “These are too small this week. Please wait to pick them.” Small green tomatoes hung from the vines. What does the writer expect?","choices":["The tomatoes will grow and ripen later.","The note will make tomatoes change color right away.","The tomatoes are ready to pick now.","The vines will be moved indoors today."],"answer":0,"explanation":""}'::jsonb,'7bb4e05e6a3e56d6a756da4024024f6a','official',NULL,NULL,'Grade 4 ELA — Making Inferences from Evidence'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--1',1,'{"question":"Meera tried to finish a kite alone. The frame bent twice. She asked Jo to hold the sticks while she tied them, and together they flew it. What theme fits?","choices":["Friends should choose identical hobbies.","Kites always fly well.","Asking for help can make a hard job possible.","Being first matters most."],"answer":2,"explanation":""}'::jsonb,'aeda233d911d93ed46b6959747b3bc5d','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--2',1,'{"question":"Meera tried to finish a kite alone. The frame bent twice. She asked Jo to hold the sticks while she tied them, and together they flew it. Which action develops this theme?","choices":["Meera asks Jo to hold the sticks.","Jo watches a kite.","The frame bends once.","Meera picks the color."],"answer":0,"explanation":""}'::jsonb,'e1d89f6f5b389c4e8e71929a5cdc0c6d','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--3',1,'{"question":"Teo set aside every crooked bowl. At the art show, a visitor chose the bowl Teo had nearly thrown out because it looked like a wave. What lesson fits?","choices":["Things can only be useful if they look the same.","Something you see as a flaw may have value.","Visitors always know the artist''s intention.","Artists should never show their work."],"answer":1,"explanation":""}'::jsonb,'250fe3070f77b204b2f0a8cf9808fb95','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--4',1,'{"question":"Teo set aside every crooked bowl. At the art show, a visitor chose the bowl Teo had nearly thrown out because it looked like a wave. Which detail gives the strongest evidence for the lesson?","choices":["Teo makes several bowls.","There is an art show.","A visitor likes the bowl Teo almost discards.","A bowl sits on a table."],"answer":2,"explanation":""}'::jsonb,'16f026a7858f0b844cba41f953da3cb7','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--5',1,'{"question":"Lena ran too fast at the start of every race and tired early. At practice she learned to keep a steady pace. In the next race she had energy at the end. What message fits?","choices":["Races should be shorter.","Practice makes every task easy.","Winning requires starting fastest.","Pacing yourself can help you reach a goal."],"answer":3,"explanation":""}'::jsonb,'e7fa47093ba66d7b7726297287e628e3','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--6',1,'{"question":"Lena ran too fast at the start of every race and tired early. At practice she learned to keep a steady pace. In the next race she had energy at the end. Which event shows Lena putting the lesson into practice?","choices":["She saves energy for the finish.","She chooses a different sport.","She runs fastest at the start again.","She leaves before the race."],"answer":0,"explanation":""}'::jsonb,'210c58cbbdd17f91bcc560b67c9019bb','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--7',1,'{"question":"Max found an extra ticket beside his seat. He wanted to keep it for a friend, but returned it. A younger child nearby stopped crying when it was found. What theme fits?","choices":["Friends should always sit together.","Doing the honest thing can help someone else.","A noisy room is hard to search.","Tickets make people impatient."],"answer":1,"explanation":""}'::jsonb,'b876ef9ac05c3b970b640bacb5c910f8','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--8',1,'{"question":"Max found an extra ticket beside his seat. He wanted to keep it for a friend, but returned it. A younger child nearby stopped crying when it was found. Which moment shows the effect of Max''s choice?","choices":["A seat is empty.","The younger child stops crying.","Max thinks about a friend.","Max notices the ticket."],"answer":1,"explanation":""}'::jsonb,'bd65b9747ecfaadf0292334aeab96b71','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--9',1,'{"question":"Ina tried three ways to make a paper bridge. After each test she changed one part. The last bridge held all the toy cars. What theme fits?","choices":["Mistakes can show what to try next.","You can always solve a problem on the first try.","More toys make a bridge stronger.","Planning matters only for bridges."],"answer":0,"explanation":""}'::jsonb,'a0f9cd5a20a14da84f5a1f7c0ce8bc59','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--10',1,'{"question":"Ina tried three ways to make a paper bridge. After each test she changed one part. The last bridge held all the toy cars. Which detail best supports the theme?","choices":["Ina changes one part after each test.","Paper comes in many colors.","The toy cars are small.","The last test happens at a table."],"answer":0,"explanation":""}'::jsonb,'87a44768dd251726e084fd4d247b645e','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--11',1,'{"question":"Ren''s team picked quiet Bea to share their design. She listened to each idea and explained how the parts worked together. The audience finally understood their plan. What message fits?","choices":["Listening carefully can help you explain a group''s ideas.","Teams must agree before hearing ideas.","Only the loudest people can lead.","A design needs a long speech."],"answer":0,"explanation":""}'::jsonb,'ca2926ea846f48c546530426d9c92114','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--12',1,'{"question":"Ren''s team picked quiet Bea to share their design. She listened to each idea and explained how the parts worked together. The audience finally understood their plan. Which action supports the message?","choices":["Ren joins the team.","The audience enters the room.","The design has several parts.","Bea listens to each teammate before speaking."],"answer":3,"explanation":""}'::jsonb,'c9647beed93c1f05935add601d9f6d8b','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--13',1,'{"question":"Aki heard a friend say the pond club was boring. She attended once and liked studying the insects. She invited the friend to visit with her. Which theme fits best?","choices":["It is best to avoid new places.","Friends must like the same things.","All clubs study insects.","Trying something yourself can change what you think."],"answer":3,"explanation":""}'::jsonb,'ff35f31a885c3a6287889f7da17df0ee','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--14',1,'{"question":"Aki heard a friend say the pond club was boring. She attended once and liked studying the insects. She invited the friend to visit with her. What event helps Aki discover the lesson?","choices":["The insects leave the pond.","She visits the club and enjoys studying insects.","Her friend refuses a visit.","She hears someone call it boring."],"answer":1,"explanation":""}'::jsonb,'e6ae3f8462cb53179db4401876e18af7','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--15',1,'{"question":"When a storm broke the garden fence, Lee wanted to blame someone. Then neighbors brought tools and repaired it together. Lee helped carry boards. What idea grows through the story?","choices":["Neighbors should bring identical tools.","A fence can stop all storms.","Working together helps more than looking for someone to blame.","Boards are more useful before rain than after it."],"answer":2,"explanation":""}'::jsonb,'ca704d6fee091e0d8662fc2261b10cd5','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--16',1,'{"question":"When a storm broke the garden fence, Lee wanted to blame someone. Then neighbors brought tools and repaired it together. Lee helped carry boards. Which detail shows Lee acting on this idea?","choices":["Lee wants to blame someone.","The neighbors see the storm.","Lee helps carry boards.","A storm breaks the fence."],"answer":2,"explanation":""}'::jsonb,'a2f58baf817062a8f3f972dba24d4507','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--17',1,'{"question":"Zara was afraid to read her poem aloud. She read just the first two lines to a friend. After several short tries, she read the whole poem at the assembly. What message fits?","choices":["Friends should write your work for you.","Small steps can help you face a fear.","Poems must rhyme to be read aloud.","An assembly should always be quiet."],"answer":1,"explanation":""}'::jsonb,'5824cc11073cc092e17242e2b2e88219','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--18',1,'{"question":"Zara was afraid to read her poem aloud. She read just the first two lines to a friend. After several short tries, she read the whole poem at the assembly. Which choice best describes Zara''s progress?","choices":["She waits for someone to read for her.","She avoids reading the poem at all.","She starts with two lines and builds confidence.","She memorizes a different poem."],"answer":2,"explanation":""}'::jsonb,'4af3b268ab1232134ba7686081717cef','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--19',1,'{"question":"Two children wanted the sunny garden bed. They learned that only one of their plants needed full sun. They shared the beds in a way that helped both plants. What theme fits?","choices":["Neighbors should all grow the same plant.","Every plant grows best in shade.","Only one person can gain from a decision.","Learning what others need can help solve a disagreement."],"answer":3,"explanation":""}'::jsonb,'be363ed4d969d8ec36053a6989db52ed','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--theme:elementary--english-language-arts--5--theme--20',1,'{"question":"Two children wanted the sunny garden bed. They learned that only one of their plants needed full sun. They shared the beds in a way that helped both plants. Which event is most important to this message?","choices":["They carry seeds to the garden.","They look at the fence.","They both point at the sunny bed.","They find out they need different amounts of sunlight."],"answer":3,"explanation":""}'::jsonb,'c33116f1d80dc76be3171120ee930dac','official',NULL,NULL,'Grade 5 ELA — Finding Theme in Short Stories'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--1',1,'{"question":"As I stepped onto the stage, I could hear my sister cheering. I had practiced the song, but my hands shook. What point of view is used?","choices":["first person","an outside news report","second person","third person"],"answer":0,"explanation":""}'::jsonb,'3adeeda05085a583c3e0b3b42a422f5d','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--2',1,'{"question":"As I stepped onto the stage, I could hear my sister cheering. I had practiced the song, but my hands shook. Which detail shows the character''s inner conflict?","choices":["Their sister cheers.","A stage has lights.","They enter a building.","Their hands shake even after practice."],"answer":3,"explanation":""}'::jsonb,'3be2bffcfb5cf7765e94c9fa0b30abbb','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--3',1,'{"question":"A storm washed out the bridge on Don''s usual road. Don drew a new route, but it meant reaching the market after it closed. How does setting shape the plot?","choices":["The road makes Don forget his name.","Don chooses what to sell at the market.","The storm affects which route Don can take.","The market sells road maps."],"answer":2,"explanation":""}'::jsonb,'3b6a7e9ae8bfa6721c7bb2622bb017e7','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--4',1,'{"question":"A storm washed out the bridge on Don''s usual road. Don drew a new route, but it meant reaching the market after it closed. What is Don''s main problem?","choices":["The usual road is blocked and the other route takes longer.","The storm starts after Don gets home.","There are too many market stalls.","Don cannot draw a bridge."],"answer":0,"explanation":""}'::jsonb,'3ac15c0889b40fb028ee3a2d6d66b367','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--5',1,'{"question":"Sol teased his cousin about collecting odd stones. After one sparked Sol''s interest, he borrowed a field guide and began a collection too. How does Sol change?","choices":["He stops noticing stones altogether.","He gets angry about field guides.","He replaces his cousin''s collection.","He comes to appreciate his cousin''s interest."],"answer":3,"explanation":""}'::jsonb,'596d141731f22d1a74b99ac1c8535132','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--6',1,'{"question":"Sol teased his cousin about collecting odd stones. After one sparked Sol''s interest, he borrowed a field guide and began a collection too. Which event turns the story toward that change?","choices":["One of the stones catches Sol''s interest.","The story ends with a new collection.","Sol jokes about the collection at first.","The cousin already owns some stones."],"answer":0,"explanation":""}'::jsonb,'6d24bf78faa8668e6ab8bc60208f6ff4','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--7',1,'{"question":"“I do not need directions,” Mina said. When her team got lost, she unfolded the map and asked everyone what they noticed. Which trait does Mina show at the end?","choices":["certainty she never needs help","willingness to accept help","avoidance of her teammates","interest only in speed"],"answer":1,"explanation":""}'::jsonb,'32191c1617422402fead7b1fe43bd945','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--8',1,'{"question":"“I do not need directions,” Mina said. When her team got lost, she unfolded the map and asked everyone what they noticed. What shows her change most directly?","choices":["She begins with a confident claim.","She asks for observations from the team.","A map can be folded.","The team gets lost."],"answer":1,"explanation":""}'::jsonb,'37e32bf3063ea1a50857cdedef99c305','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--9',1,'{"question":"At midnight the lookout heard a crack below the ice. She lifted the lantern and saw water spreading across the path. Which detail most directly contributes to a tense mood?","choices":["the path''s name","the crack below the ice","the existence of a lookout","the type of lantern handle"],"answer":1,"explanation":""}'::jsonb,'6f7f1b620edec7a37652f7739ca74138','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--10',1,'{"question":"At midnight the lookout heard a crack below the ice. She lifted the lantern and saw water spreading across the path. When does this scene take place?","choices":["at breakfast","in the late afternoon","around midnight","at sunrise"],"answer":2,"explanation":""}'::jsonb,'1730cd3a25b6eab07530ac2a5418a889','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--11',1,'{"question":"Dev wanted to finish the tower before the timer rang. The bottom leaned, so he took it apart and built a wider base. It stood when the timer rang. What resolves the problem?","choices":["Dev builds a wider base.","The tower starts to lean.","Dev hopes to work quickly.","The timer has a loud bell."],"answer":0,"explanation":""}'::jsonb,'cce962976b7792b3f8ae5c8d2defad82','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--12',1,'{"question":"Dev wanted to finish the tower before the timer rang. The bottom leaned, so he took it apart and built a wider base. It stood when the timer rang. Which event raises the stakes before the resolution?","choices":["The base begins to lean as time runs short.","The rebuilt tower stays up.","The timer rings at the end.","Dev leaves with a standing tower."],"answer":0,"explanation":""}'::jsonb,'560d80e2ecc21a8a39b84ad6c91fecfc','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--13',1,'{"question":"Neither Lee nor Kam wanted to give up the drum for the solo. Then they tried alternating lines and decided to perform as a pair. What kind of conflict begins the story?","choices":["character against wild animals","character against a machine","character against weather","character against character"],"answer":3,"explanation":""}'::jsonb,'df0e161f9a56ab71f6113c62db0b5e5f','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--14',1,'{"question":"Neither Lee nor Kam wanted to give up the drum for the solo. Then they tried alternating lines and decided to perform as a pair. What event makes the ending possible?","choices":["They both want a solo.","The drum is on a stage.","They try alternating lines.","They ask to perform on different days."],"answer":2,"explanation":""}'::jsonb,'20a85b3167bc47073a5829199789ee22','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--15',1,'{"question":"At the old station, Ada tucked a coin inside a crack in the wall. Ten years later she returned and found it still there. What signals the jump in time?","choices":["“old station”","“in the wall”","“a coin”","“Ten years later”"],"answer":3,"explanation":""}'::jsonb,'e20b6da6fe6afdcfb7eb7086fde3f139','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--16',1,'{"question":"At the old station, Ada tucked a coin inside a crack in the wall. Ten years later she returned and found it still there. Which object connects the two scenes?","choices":["a train","the coin","a clock","a ticket"],"answer":1,"explanation":""}'::jsonb,'765047032f0ef1461a49bd4bf43ea15f','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--17',1,'{"question":"In the dry summer, the creek shrank to a few pools. Jo carried the stranded fish to a deeper pool with help from a ranger. Which best describes the main conflict?","choices":["Two rangers argue about directions.","A machine breaks during a race.","A character fights a classroom rule.","A character responds to a problem caused by nature."],"answer":3,"explanation":""}'::jsonb,'96cb0fe5535ef4599ca2d31a8050f077','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--18',1,'{"question":"In the dry summer, the creek shrank to a few pools. Jo carried the stranded fish to a deeper pool with help from a ranger. What motivates Jo most directly?","choices":["wanting to make the pools disappear","wanting to help the stranded fish","wanting to dam the creek","wanting to find a ranger''s badge"],"answer":1,"explanation":""}'::jsonb,'04cd62ed51f9d1482ccec8a45cb946c3','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--19',1,'{"question":"The narrator describes Lina''s hope aloud to the reader, then tells what Pax secretly fears. Lina and Pax do not know each other''s thoughts. What does the narrator know?","choices":["only the place and time","only Lina''s words","private thoughts of more than one character","only what the reader thinks"],"answer":2,"explanation":""}'::jsonb,'7b67b735ce469c55bf4bd75d05dd4e81','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--literary-elements:elementary--english-language-arts--5--literary-elements--20',1,'{"question":"The narrator describes Lina''s hope aloud to the reader, then tells what Pax secretly fears. Lina and Pax do not know each other''s thoughts. What can this narration show that Lina alone could not report?","choices":["the location of the scene Lina sees","what Lina hopes will happen","Pax''s private fear","Lina''s own words"],"answer":2,"explanation":""}'::jsonb,'29fbaf5aeb151fa72e6102a9cdfead6f','official',NULL,NULL,'Grade 5 ELA — How Story Elements Work Together'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--1',1,'{"question":"Which revision keeps the verbs in the same tense?","choices":["We sketched the leaf and labeled its veins.","We sketch the leaf and will labeled its veins.","We sketch the leaf and labeled its veins.","We sketched the leaf and label its veins."],"answer":0,"explanation":""}'::jsonb,'56ef3bd805d7c0c402da08c99e5b42bd','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
