('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--3',1,'{"question":"Choose the pronoun: Please hand the charts to Rosa and __.","choices":["mine","me","my","I"],"answer":1,"explanation":""}'::jsonb,'7ab226f11993f82518bc9f88d3481860','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--4',1,'{"question":"Which revision clarifies that Malik finished the model?","choices":["After Malik finished the model, he called Lee.","Malik called Lee after he finished it.","He finished it after Lee''s call.","After he finished it, Lee got a call."],"answer":0,"explanation":""}'::jsonb,'04be899f7623156c063f3f371f5d5e42','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--5',1,'{"question":"Which word shows a contrast? “It was late, __ we continued working.”","choices":["and then","so","yet","because"],"answer":2,"explanation":""}'::jsonb,'eca5f38b375a2cf215aba0bd202cf933','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--6',1,'{"question":"Which pair of conjunctions completes the idea? “__ the pen __ the pencil is in my bag; both are on my desk.”","choices":["Not only … but also","Both … and","Either … or","Neither … nor"],"answer":3,"explanation":""}'::jsonb,'de788285fce8b09355fc18fe1b98f33d','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--7',1,'{"question":"Which has a comma after an introductory phrase?","choices":["After, the game we returned the balls.","After the game we, returned the balls.","After the game we returned, the balls.","After the game, we returned the balls."],"answer":3,"explanation":""}'::jsonb,'e64b4b4051eaacacd0d614164cd4b15c','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--8',1,'{"question":"Which joins two full ideas correctly with “but”?","choices":["The room was cold but, the water stayed warm.","The room was cold, but the water stayed warm.","The room, was cold but the water stayed warm.","The room was cold, but, the water stayed warm."],"answer":1,"explanation":""}'::jsonb,'ba0fe548cc79175cfa5c60175063222c','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--9',1,'{"question":"Choose the verb that agrees with the subject: “The box of colored pencils __ on the top shelf.”","choices":["were","are","have","is"],"answer":3,"explanation":""}'::jsonb,'3d9c599794aadeef7cff1b4b1e89b164','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--10',1,'{"question":"Which sentence uses the correct form of “to lie” in the present?","choices":["The cat lie in the sun each morning.","The cat lying in the sun each morning.","The cat lies in the sun each morning.","The cat lays in the sun each morning."],"answer":2,"explanation":""}'::jsonb,'b2fe96c5bee7049141d6230f507cf609','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--11',1,'{"question":"Which revision avoids a fragment?","choices":["Turning back at the trail.","Because the trail flooded.","Because the trail flooded, we turned back.","The flooded trail after rain."],"answer":2,"explanation":""}'::jsonb,'6e2184da641b803f696211179db8859c','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
