('original:elementary--english-language-arts--5--advanced-grammar:elementary--english-language-arts--5--advanced-grammar--20',1,'{"question":"Which choice uses parallel verb forms?","choices":["We like hiking, paddle, and to skate.","We like to hike, paddling, and skate.","We like hiking, paddling, and skating.","We like hike, paddling, and skating."],"answer":2,"explanation":""}'::jsonb,'54b52151f3f212a8d3b0d578f7bc83b9','official',NULL,NULL,'Grade 5 ELA — Editing for Clarity and Grammar'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--1',1,'{"question":"“We should plant a tree near the benches. Its shade would keep them cooler at lunch.” Why did the author most likely write this?","choices":["to tell a story about a tree","to explain how to measure a bench","to persuade people to plant a tree","to describe a tree that already grew there"],"answer":2,"explanation":""}'::jsonb,'ee75c700529e1da897edcdc5390b4221','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--2',1,'{"question":"“We should plant a tree near the benches. Its shade would keep them cooler at lunch.” Which words best signal that purpose?","choices":["“at lunch”","“keep them cooler”","“We should plant”","“near the benches”"],"answer":2,"explanation":""}'::jsonb,'0cec4066634b0fdac95559c7a5c99da0','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--3',1,'{"question":"“When warm air cools, some water vapor becomes tiny drops. A group of these drops can form a cloud.” What is the main purpose?","choices":["to explain how clouds can form","to tell a story about one storm","to convince people to stay inside","to teach readers how to make a kite"],"answer":0,"explanation":""}'::jsonb,'dc499ad66d80c4d0feef986da58f6f61','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
