('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--5',1,'{"question":"“The goose stole the mayor''s hat and wore it to the parade. By noon, the mayor was marching in a nest.” What is the main purpose?","choices":["to report election results","to explain goose behavior using data","to teach readers to weave hats","to entertain with an unlikely story"],"answer":3,"explanation":""}'::jsonb,'d3a8863741ee8715ed0ba9fb8d140218','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--6',1,'{"question":"“The goose stole the mayor''s hat and wore it to the parade. By noon, the mayor was marching in a nest.” Which feature supports the purpose?","choices":["a humorous and unlikely event","a set of repair steps","a chart with facts","a warning in bold text"],"answer":0,"explanation":""}'::jsonb,'bbfec63d323986a180c46da7f89b91bf','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--7',1,'{"question":"“Step 1: Fill the tray halfway. Step 2: Place seeds on the soil. Step 3: Add a thin layer of soil.” What is the author trying to do?","choices":["persuade readers to buy a tray","tell a folktale","compare three kinds of seeds","guide readers through planting seeds"],"answer":3,"explanation":""}'::jsonb,'5b4a10bfe19ce7678e8a662af81b557b','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--8',1,'{"question":"“Step 1: Fill the tray halfway. Step 2: Place seeds on the soil. Step 3: Add a thin layer of soil.” Which feature serves this purpose most directly?","choices":["a price sticker","a drawing of shade","an author biography","numbered steps"],"answer":3,"explanation":""}'::jsonb,'418f618d8ad08b9849a1c955f688f40a','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--9',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” Where would this message be most useful?","choices":["on a notice for library borrowers","on a road map","in a book catalog''s subject index","in a story about gardening"],"answer":0,"explanation":""}'::jsonb,'78896f48b8f984c939e26b66e88c11df','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--10',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” What is the purpose of including “by Friday”?","choices":["give readers a deadline","name a type of book","tell readers who wrote it","show how the basket was made"],"answer":0,"explanation":""}'::jsonb,'50cf6bdc8a67645873ecd183e9d6d67d','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--11',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” Which line is mainly meant to persuade?","choices":["The station stands beside the sink.","Our class counted twelve cups on Thursday.","Choose the refill station so our class uses fewer cups.","Water flows when the button is pressed."],"answer":2,"explanation":""}'::jsonb,'b2a37fd979bc97d75fea16406cacb23e','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--12',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” Which text would best inform a reader about where oak trees grow?","choices":["a fictional scene about a talking oak","a guide with maps and habitat descriptions","a poem comparing oak leaves to hands","an ad selling oak furniture"],"answer":1,"explanation":""}'::jsonb,'9ad99ceb57cdffefe088f541a5393fff','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--13',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” What is the likely purpose of a photo caption naming each part of a bicycle?","choices":["to argue every person needs a bicycle","to identify parts readers can see","to entertain with a riddle","to recount a race finish"],"answer":1,"explanation":""}'::jsonb,'93a5e392abe633d64ab6043cb4ed0bd9','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--14',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” Which is most useful to readers deciding whether to join an after-school club?","choices":["the price of a bus ticket in another city","the age of a different club''s founder","meeting times and examples of activities","the hall''s paint color"],"answer":2,"explanation":""}'::jsonb,'306a5d2da07f41618b76e982d38baa28','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--15',1,'{"question":"“Return books by Friday so others can check them out. Leave returns in the basket by the door.” Which line mainly explains a cause?","choices":["I slipped twice and laughed.","The path became muddy because of heavy rain.","Let''s close the path today.","Bring boots when you walk the path."],"answer":1,"explanation":""}'::jsonb,'2f209c7b2dfee7a9dc7c4c240cf0946c','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--16',1,'{"question":"An article describes two bus routes, with the costs and times for each. What is its likely purpose?","choices":["to make readers laugh","to help readers compare travel options","to persuade everyone to choose the same bus","to describe bus engine parts"],"answer":1,"explanation":""}'::jsonb,'ecaa3a94333650ba3c5b62f859330ed5','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--17',1,'{"question":"“Only three days left to support our shelter! Your gift can pay for food and blankets.” What does the author want readers to do?","choices":["learn how days are counted","compare fabric types","draw a picture of a blanket","donate to the shelter"],"answer":3,"explanation":""}'::jsonb,'1d6ee638ea81e6639f57dae34b920ec4','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--18',1,'{"question":"“I remember the squeak of the porch swing on summer nights, and the cool wood under my bare feet.” What is a likely purpose of these details?","choices":["to persuade readers to remove a porch","to compare two towns using data","to teach steps for building a swing","to help readers experience a personal memory"],"answer":3,"explanation":""}'::jsonb,'bc202fd5297388f0a27151df37c01baf','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--19',1,'{"question":"“I remember the squeak of the porch swing on summer nights, and the cool wood under my bare feet.” Which headline most clearly signals an explanation?","choices":["Vote for a New Park","Come Buy Our Leaf Prints","Why Some Leaves Change Color","The Leaf That Learned to Speak"],"answer":2,"explanation":""}'::jsonb,'2393421d7e7c6eddc4562dd5918a5e47','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--authors-purpose:elementary--english-language-arts--5--authors-purpose--20',1,'{"question":"“The trail entrance has moved. Begin your hike beside the visitor center until repairs are finished.” Why does the notice address hikers?","choices":["to sell equipment at the center","to direct them to a temporary entrance","to teach where visitors used to live","to entertain them before the hike"],"answer":1,"explanation":""}'::jsonb,'dad7f6ed8ed711118f2cce3ebdeccdf2','official',NULL,NULL,'Grade 5 ELA — Why Authors Write and How You Can Tell'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--1',1,'{"question":"Text A: Our town painted bike lanes on Main Street to make space for riders. Text B: Riders asked for a rack next to the market so they could lock their bikes. What do both texts describe?","choices":["reasons to close the market","how to fix a flat tire","plans to widen highways","ways a town can support people who bike"],"answer":3,"explanation":""}'::jsonb,'4191bef59da2b30d38338a452a398cd7','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--2',1,'{"question":"Text A: Our town painted bike lanes on Main Street to make space for riders. Text B: Riders asked for a rack next to the market so they could lock their bikes. Which detail comes only from Text B?","choices":["The town uses streets.","The changes concern biking.","The town painted Main Street bike lanes.","Riders asked for a place to lock bikes."],"answer":3,"explanation":""}'::jsonb,'393a7227f81d533f8a76dc162bed696d','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--3',1,'{"question":"Text A: Volunteers carried records upstairs before the river flooded the library. Text B: After flooding, neighbors helped dry books and replace wet shelves. How do the texts differ?","choices":["A describes cleanup; B describes preparing.","A is about a school flood; B is about forest fires.","A describes preparing for a flood; B describes cleanup.","A describes repairs; B explains why it rained."],"answer":2,"explanation":""}'::jsonb,'2292093497045f032f68759df487b550','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--4',1,'{"question":"Text A: Volunteers carried records upstairs before the river flooded the library. Text B: After flooding, neighbors helped dry books and replace wet shelves. Which summary covers both?","choices":["A river flooded because books were moved.","People helped protect and restore a library around the time of a flood.","Neighbors rebuilt an entire town before a storm.","Volunteers closed a library and never returned."],"answer":1,"explanation":""}'::jsonb,'05ff99a971a6f778fe5ae5c57b44839d','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--5',1,'{"question":"Text A: Wood chips spread over garden soil slowed water loss. Text B: Fallen leaves covered the soil and decomposed into organic matter. What do both materials do at first?","choices":["stop all rain from falling","pull seeds out of the ground","turn soil to plastic","cover the soil"],"answer":3,"explanation":""}'::jsonb,'22f10bb247f3a5d1c5a6b61b4a54c005','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--6',1,'{"question":"Text A: Wood chips spread over garden soil slowed water loss. Text B: Fallen leaves covered the soil and decomposed into organic matter. What result is stated only in Text B?","choices":["Water loss slowed.","The material decomposed into organic matter.","The garden got more rain.","The soil was covered."],"answer":1,"explanation":""}'::jsonb,'7d2c0164f1b95605160e99d7aac295e7','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--7',1,'{"question":"Text A: An owl hunts after dark and can find prey with its hearing. Text B: A hawk often hunts during the day and can see small prey from far away. Which contrast is supported?","choices":["Both birds only hunt after dark.","The owl cannot hunt moving prey.","The hawk hunts only by hearing.","The texts emphasize hearing for the owl and sight for the hawk."],"answer":3,"explanation":""}'::jsonb,'72d3a48dd6ed7ea891968ba41d012b95','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--8',1,'{"question":"Text A: An owl hunts after dark and can find prey with its hearing. Text B: A hawk often hunts during the day and can see small prey from far away. Which detail supports a claim about the owl''s hearing?","choices":["It has large wings.","It can find prey using sound after dark.","It can see small prey from far away.","It always hunts beside water."],"answer":1,"explanation":""}'::jsonb,'5b6fb2ef29e5199879acdc7432a8aa71','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--9',1,'{"question":"Text A: The school counted 80 plastic bottles in the trash one week. Text B: After a refill station opened, the school counted 45 bottles the next week. What does the comparison show?","choices":["The second week''s count was lower.","Bottles became heavier.","The first count was smaller.","The refill station opened years earlier."],"answer":0,"explanation":""}'::jsonb,'25b4882fa8ad3858d50df08c550f8e12','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--10',1,'{"question":"Text A: The school counted 80 plastic bottles in the trash one week. Text B: After a refill station opened, the school counted 45 bottles the next week. Which claim needs more evidence?","choices":["One count was 80.","The station was open by the second count.","The station caused all of the drop in bottles.","The second count was 45."],"answer":2,"explanation":""}'::jsonb,'871f35f29989e8090bb02c498f61d67a','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--11',1,'{"question":"Text A: A diary describes a winter market and the smell of fresh bread. Text B: A store ledger lists loaves sold and prices for each day. Which source gives the writer''s personal experience directly?","choices":["Text A","neither text","Text B","both texts equally"],"answer":0,"explanation":""}'::jsonb,'c36313a6072f60644bfdff85a049510f','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--12',1,'{"question":"Text A: A diary describes a winter market and the smell of fresh bread. Text B: A store ledger lists loaves sold and prices for each day. Which question is Text B best suited to answer?","choices":["How many loaves were sold each day?","How did buyers feel about the bread?","What did the baker feel about winter?","What did each loaf smell like?"],"answer":0,"explanation":""}'::jsonb,'c26eaa7169dba53fbbc13bb09fae1bda','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--13',1,'{"question":"Text A: A class built birdhouses with small doors for small birds. Text B: A class built bat boxes with narrow gaps for bats to enter. Which shared idea fits both?","choices":["A shelter''s entrance can suit the animal that uses it.","Neither shelter needs an entrance.","Bats and birds use identical shelters.","All animals need the same door size."],"answer":0,"explanation":""}'::jsonb,'a3918ab250a8c1b06bb1f7a02ec3ccd8','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--14',1,'{"question":"Text A: A class built birdhouses with small doors for small birds. Text B: A class built bat boxes with narrow gaps for bats to enter. Which difference is stated in the texts?","choices":["Only the bat shelter was built by students.","Both groups studied bats.","One shelter uses a small door; the other uses a narrow gap.","The birdhouse was put in a cave."],"answer":2,"explanation":""}'::jsonb,'0371cf7c3b079f0ff88d2f34163ae28f','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--15',1,'{"question":"Text A: The long trail stays on firm ground most of the year. Text B: The short route passes low ground that turns muddy after storms. Which route would a hiker likely choose to avoid mud after rain?","choices":["the short route","neither route because both are stated to flood","the long trail","either one because the ground is described as the same"],"answer":2,"explanation":""}'::jsonb,'ace913f9b255073c6348cda6bbb20498','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts'),
('original:elementary--english-language-arts--5--reading-comprehension:elementary--english-language-arts--5--reading-comprehension--16',1,'{"question":"Text A: The long trail stays on firm ground most of the year. Text B: The short route passes low ground that turns muddy after storms. What is one tradeoff shown in the texts?","choices":["The shorter route may be muddier.","The short path is farther from its start.","Both paths are always dry.","The longer route closes every day."],"answer":0,"explanation":""}'::jsonb,'d255c5c6c13e4fdf07e00c7487bade9c','official',NULL,NULL,'Grade 5 ELA — Reading and Comparing Short Texts')
